10	const BASE_PREMIUMS: Record<string, number> = {
11	  sword: 100,
12	  amulet: 60,
13	};
14	
15	const FIRST_INSURANCE_SURCHARGE = 0.1;
16	
17	const premiumForItems = (items: Item[]): number => {
18	  const base = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
19	  return base + base * FIRST_INSURANCE_SURCHARGE;
20	};
21	
22	export const runScenario = (scenario: Scenario): ScenarioResult => ({
23	  results: scenario.steps.map((step) => ({
24	    premium: premiumForItems(step.items ?? []) + PROCESSING_FEE,
25	  })),
26	});
