const basePremiumOf = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

const quotePremium = (items: Item[]): number => {
  const basePremium = basePremiumOf(items);
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE;
  return basePremium + firstInsuranceSurcharge + PROCESSING_FEE;
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => ({
    premium: quotePremium(step.items ?? []),
  })),
});
